"""Português — virtudes (virtues_001 … virtues_050)."""

T = {
"virtues_001": ("Segundo um hadith narrado pelo imã al-Bukhari, o que deve fazer com as suas palavras quem crê em Allah e no Último Dia?", ["Dizer o bem ou calar-se", "Falar alto", "Nunca falar", "Repetir boatos"], "O Profeta ﷺ disse: «Quem crê em Allah e no Último Dia, que diga o bem ou que se cale»."),
"virtues_002": ("Segundo esse mesmo hadith, quem mais deve o crente honrar, além do seu hóspede?", ["O seu vizinho", "O seu comerciante", "O seu rival", "Um desconhecido"], "O hadith continua: «…e quem crê em Allah e no Último Dia, que honre o seu vizinho»."),
"virtues_003": ("Esse mesmo hadith também menciona honrar quem, quando chega a casa de alguém?", ["O hóspede", "Só o vizinho", "O comerciante", "Um viajante desconhecido e distante"], "O hadith completo diz: «…quem crê em Allah e no Último Dia, que honre o seu hóspede»."),
"virtues_004": ("Segundo um hadith autêntico, a fé de um crente não é completa até que ame para o seu irmão o que ama para…", ["si mesmo", "a sua riqueza", "só a sua família", "o seu país"], "O Profeta ﷺ disse: «Nenhum de vós crê verdadeiramente até que ame para o seu irmão o que ama para si mesmo»."),
"virtues_005": ("Segundo um hadith autêntico, o verdadeiro muçulmano é aquele de cuja língua e ___ os outros estão a salvo.", ["mão", "riqueza", "olhar", "voz"], "O Profeta ﷺ disse: «O muçulmano é aquele de cuja língua e mão os outros muçulmanos estão a salvo»."),
"virtues_006": ("O Alcorão ordena a bondade para com os pais e proíbe dizer-lhes até que palavra de enfado?", ["«Uf» (um som de impaciência)", "«Não»", "«Basta»", "«Espera»"], "O Alcorão exige a máxima bondade para com os pais, proibindo até a mais leve palavra de desprezo."),
"virtues_007": ("Com que compara o Alcorão a maledicência (falar mal de um ausente)?", ["Com comer a carne do próprio irmão morto", "Com beber água salgada", "Com caminhar na escuridão", "Com semear na areia"], "«Gostaria algum de vós de comer a carne do seu irmão morto? Detestá-lo-íeis!»: assim é feia a maledicência."),
"virtues_008": ("Como descreve o Alcorão a relação entre os crentes?", ["São irmãos", "São concorrentes", "São estranhos", "São sócios comerciais"], "«Os crentes não são senão irmãos; reconciliai, pois, os vossos dois irmãos.»"),
"virtues_009": ("O que diz o Alcorão sobre troçar dos outros?", ["É proibido: os troçados podem ser melhores do que os troçadores", "É permitido entre amigos", "É permitido se tiver graça", "É reservado aos poetas"], "«Que uns não troçem dos outros: talvez sejam melhores do que eles.»"),
"virtues_010": ("Segundo o Alcorão, o que promete Allah a quem é agradecido?", ["Dar-lhe mais", "Uma longa vida", "Riqueza imediata", "Uma viagem"], "«Se fordes agradecidos, dar-vos-ei mais.»"),
"virtues_011": ("Segundo o Alcorão, como receberão a sua recompensa os pacientes (sabirun)?", ["Completa, sem medida", "Toda de uma vez", "Depois de quarenta dias", "Segundo a sua riqueza"], "«Os pacientes receberão a sua recompensa completa, sem conta.»"),
"virtues_012": ("«Comei e bebei, mas…»: como continua este versículo?", ["Não desperdiceis", "Não partilheis", "Não faleis", "Não saiais"], "«Comei e bebei, mas não vos excedais: Allah não ama os desperdiçadores.»"),
"virtues_013": ("Que versículo, muitas vezes recitado no sermão de sexta-feira, resume o que Allah ordena?", ["«Allah ordena a justiça e o bem»", "«Allah ordena o comércio»", "«Allah ordena viajar»", "«Allah ordena o silêncio»"], "«Allah ordena a justiça, o bem e a generosidade para com os parentes…»: recita-se todas as sextas-feiras."),
"virtues_014": ("Contra quem começa a surata Al-Mutaffifin com «Ai de…»?", ["Os que defraudam na medida e no peso", "Os que dormem", "Os que viajam", "Os que se calam"], "«Ai dos defraudadores: que exigem a medida completa ao receber, mas dão a menos ao medir para os outros!»"),
"virtues_015": ("Segundo a surata Ad-Duha, como se deve tratar o órfão e aquele que pede?", ["Nem oprimi-los nem rejeitá-los", "Ignorá-los", "Enviá-los a outros", "Falar-lhes mais tarde"], "«Ao órfão, não o oprimas; e ao que pede, não o rejeites.»"),
"virtues_016": ("Como ordena o Alcorão que se fale às pessoas?", ["Com boas palavras", "Em voz muito baixa", "O menos possível", "Só aos parentes"], "«…e falai às pessoas com bondade»: a palavra amável é, em si mesma, adoração."),
"virtues_017": ("Nos seus conselhos ao filho, o que diz Luqman sobre o andar e o orgulho?", ["Não andes pela terra com arrogância", "Anda sempre depressa", "Anda só de noite", "Nunca andes sozinho"], "«Não voltes o rosto às pessoas com orgulho, nem andes pela terra com arrogância.»"),
"virtues_018": ("Segundo o primeiríssimo hadith da coleção de al-Bukhari, de que dependem as ações?", ["Das intenções", "Dos resultados", "Dos hábitos", "Das testemunhas"], "«As ações dependem das intenções, e cada pessoa terá o que tiver pretendido.»"),
"virtues_019": ("Segundo um hadith de al-Bukhari, aonde conduz a veracidade (sidq)?", ["À retidão, e a retidão conduz ao Paraíso", "À riqueza", "À fama", "À força"], "«A veracidade conduz à retidão, e a retidão conduz ao Paraíso; a mentira conduz à perversidade, e a perversidade ao Fogo.»"),
"virtues_020": ("Segundo um hadith autêntico, quais são os três sinais do hipócrita?", ["Mente ao falar, quebra a promessa e trai a confiança", "Dorme, come e fala demais", "Viaja, negoceia e canta", "Reza pouco, jejua pouco e lê pouco"], "«Os sinais do hipócrita são três: quando fala mente, quando promete não cumpre, e quando lhe confiam algo trai.»"),
"virtues_021": ("Um homem pediu conselho ao Profeta ﷺ; o que lhe repetiu ele várias vezes?", ["«Não te irrites»", "«Viaja muito»", "«Come pouco»", "«Fala alto»"], "O homem disse: «Aconselha-me». Respondeu: «Não te irrites». O homem insistiu, e ele repetiu: «Não te irrites»."),
"virtues_022": ("Segundo o Profeta ﷺ, quem é verdadeiramente forte?", ["Quem se domina na ira", "Quem ganha na luta", "Quem carrega os pesos maiores", "Quem corre mais depressa"], "«O forte não é o que vence os outros na luta; o forte é o que se domina no momento da ira.»"),
"virtues_023": ("Segundo um hadith de al-Bukhari, de que faz parte o pudor (haya')?", ["Da fé", "Da fraqueza", "Da riqueza", "Da timidez censurável"], "Ao ver um homem repreender o irmão pelo seu pudor, o Profeta ﷺ disse: «Deixa-o, pois o pudor faz parte da fé»."),
"virtues_024": ("O que disse o Profeta ﷺ a um homem que se gabava de nunca ter beijado nenhum dos seus dez filhos?", ["«Quem não tem misericórdia não receberá misericórdia»", "«Tens razão»", "«As crianças não importam»", "«É um assunto privado»"], "O Profeta ﷺ beijava os netos; a Al-Aqra', que se admirou, respondeu: «Man la yarham la yurham»."),
"virtues_025": ("Segundo um hadith de al-Bukhari, por que ato foi perdoado um homem?", ["Por dar de beber a um cão sedento", "Por construir um poço", "Por plantar uma árvore", "Por afugentar um lobo"], "O homem desceu a um poço, encheu o sapato de água e deu de beber ao cão que arfava de sede; Allah perdoou-o."),
"virtues_026": ("Segundo um hadith autêntico, porque foi castigada uma mulher?", ["Por fechar um gato sem o alimentar nem o deixar procurar comida", "Por vender um gato", "Por expulsar um gato de casa", "Por adotar gatos a mais"], "«Uma mulher foi castigada por um gato que fechou até morrer: nem o alimentou nem o deixou comer das criaturas da terra.»"),
"virtues_027": ("De quem disse o Profeta ﷺ que Jibril lhe fez tantas recomendações que pensou que o faria herdeiro?", ["Do vizinho", "Do hóspede", "Do órfão", "Do viajante"], "«Jibril não parou de me recomendar o vizinho, ao ponto de eu pensar que o faria herdar.»"),
"virtues_028": ("Segundo um hadith de al-Bukhari, quantos direitos tem o muçulmano sobre o seu irmão muçulmano?", ["Cinco", "Três", "Sete", "Dez"], "«Devolver a saudação, visitar o doente, acompanhar o funeral, aceitar o convite e responder a quem espirra.»"),
"virtues_029": ("À pergunta «Que islão é o melhor?», o que respondeu o Profeta ﷺ?", ["Dar de comer e saudar quem conheces e quem não conheces", "Construir mesquitas", "Viajar muito", "Falar pouco"], "«Dar de comer, e dirigir a saudação a quem conheces e a quem não conheces.»"),
"virtues_030": ("Com que compara o Profeta ﷺ os crentes no seu afeto e entreajuda?", ["Com um só corpo: se um membro sofre, todo o corpo vela com febre", "Com uma floresta", "Com uma caravana", "Com um rebanho"], "«Os crentes, no seu amor, misericórdia e compaixão mútuos, são como um só corpo.»"),
"virtues_031": ("Segundo o Profeta ﷺ, o que é «a mais mentirosa das palavras»?", ["A suspeita (zann)", "A poesia", "A brincadeira", "O silêncio"], "«Guardai-vos da suspeita, pois a suspeita é a mais mentirosa das palavras.»"),
"virtues_032": ("Segundo um hadith autêntico, quantos dias no máximo pode um muçulmano deixar de falar ao seu irmão?", ["Três dias", "Sete dias", "Um mês", "Um ano"], "«Não é lícito a um homem deixar de falar ao seu irmão mais de três noites… e o melhor dos dois é o que saúda primeiro.»"),
"virtues_033": ("Segundo o Profeta ﷺ, qual é o valor de cada boa ação, por pequena que seja?", ["É uma esmola (sadaqa)", "Não conta", "Vale um dinar", "Substitui a oração"], "«Toda boa ação é uma esmola.»"),
"virtues_034": ("Segundo um hadith de Sahih Muslim, qual é o ramo mais humilde da fé?", ["Retirar do caminho o que prejudica", "Construir uma mesquita", "Recitar um juz'", "Jejuar um dia"], "«A fé tem setenta e tal ramos: o mais alto é “la ilaha illa Allah”, o mais humilde é retirar do caminho o que prejudica; e o pudor é um ramo da fé.»"),
"virtues_035": ("Segundo um hadith de Sahih Muslim, a limpeza (tahara) é…", ["Metade da fé", "Um terço da fé", "Um décimo da fé", "Alheia à fé"], "«A pureza é metade da fé, e “al-hamdu li-Llah” enche a balança.»"),
"virtues_036": ("O Profeta ﷺ disse: «A religião é nasiha (conselho sincero)». Para com quem?", ["Para com Allah, o Seu Livro, o Seu Mensageiro, os dirigentes e todos os muçulmanos", "Só para consigo mesmo", "Para com os ricos", "Para com os estranhos"], "Perguntaram: «Para com quem?». Disse: «Para com Allah, o Seu Livro, o Seu Mensageiro, os dirigentes dos muçulmanos e o seu povo comum»."),
"virtues_037": ("Segundo um hadith de Sahih Muslim, o que olha Allah nos Seus servos?", ["Os seus corações e as suas ações", "A sua aparência", "A sua riqueza", "O seu número"], "«Allah não olha para os vossos corpos nem para a vossa aparência, mas olha para os vossos corações e as vossas ações.»"),
"virtues_038": ("Segundo um hadith de Sahih Muslim, o que faz Allah por quem alivia um crente de uma dificuldade deste mundo?", ["Alivia-o de uma dificuldade do Dia da Ressurreição", "Torna-o rico", "Concede-lhe longa vida", "Torna-o famoso"], "«Quem aliviar um crente de uma pena deste mundo, Allah aliviá-lo-á de uma pena do Dia da Ressurreição.»"),
"virtues_039": ("Segundo o Profeta ﷺ, o que faz Allah por quem percorre um caminho em busca de conhecimento?", ["Facilita-lhe um caminho para o Paraíso", "Dispensa-o de rezar", "Torna-o rico", "Torna-o rei"], "«A quem percorrer um caminho em busca de conhecimento, Allah facilitar-lhe-á com isso um caminho para o Paraíso.»"),
"virtues_040": ("Segundo um hadith de al-Bukhari, quem é «o melhor de vós»?", ["Quem aprende o Alcorão e o ensina", "Quem fala melhor", "Quem mais possui", "Quem mais viaja"], "«O melhor de vós é quem aprende o Alcorão e o ensina.»"),
"virtues_041": ("Como definiu o Profeta ﷺ a arrogância (kibr)?", ["Rejeitar a verdade e desprezar as pessoas", "Usar roupa bonita", "Gostar de bons sapatos", "Andar depressa"], "Ao homem que gostava de roupa bonita disse: «Allah é belo e ama a beleza. A arrogância é rejeitar a verdade e desprezar as pessoas»."),
"virtues_042": ("Segundo um hadith de al-Bukhari, quais são as duas bênçãos que muita gente desaproveita?", ["A saúde e o tempo livre", "O dinheiro e a fama", "A força e a beleza", "A família e os amigos"], "«Há duas bênçãos em que muita gente sai a perder: a saúde e o tempo livre.»"),
"virtues_043": ("Completa este hadith: «O crente não é picado duas vezes…»", ["«…do mesmo buraco»", "«…pelo mesmo escorpião»", "«…no mesmo dia»", "«…pela mesma abelha»"], "«La yuldaghu al-mu'minu min juhrin wahidin marratayn»: o crente aprende com os seus erros."),
"virtues_044": ("Com que compara o Profeta ﷺ o bom companheiro, por oposição ao ferreiro?", ["Com o vendedor de almíscar", "Com o padeiro", "Com o pastor", "Com o vendedor de tecidos"], "«O bom companheiro é como o portador de almíscar: dá-te um pouco, ou compras-lhe, ou sentes o seu perfume; o mau é como o fole do ferreiro.»"),
"virtues_045": ("Segundo um hadith de al-Bukhari, de que é responsável cada um de nós, «como um pastor»?", ["Dos que estão a seu cargo", "Do tempo", "Das estrelas", "Das colheitas dos outros"], "«Cada um de vós é um pastor, e cada um é responsável pelo seu rebanho»: o governante pelo seu povo, o homem pela sua família, a mulher pela sua casa."),
"virtues_046": ("Segundo o Alcorão, o que acontece se se repele o mal com o que é melhor?", ["Quem era inimigo torna-se como um amigo próximo", "O mal desaparece da terra", "Fica-se rico", "Nada muda"], "«Repele o mal com o que é melhor, e aquele com quem tinhas inimizade será como um amigo próximo» (41:34)."),
"virtues_047": ("Como respondem «os servos do Misericordioso» aos ignorantes que os provocam, segundo a surata Al-Furqan?", ["Dizem: «Paz!»", "Respondem com ira", "Troçam deles", "Batem-lhes"], "«Os servos do Misericordioso andam pela terra com humildade, e quando os ignorantes lhes falam, dizem: Paz!» (25:63)."),
"virtues_048": ("O que diz o Alcorão sobre o compromisso (a promessa, o pacto)?", ["«Cumpri o compromisso, pois do compromisso se pedirão contas»", "«Uma promessa não obriga ninguém»", "«Prometei só aos ricos»", "«Nunca prometais»"], "«E cumpri o compromisso, pois do compromisso se pedirão contas» (17:34)."),
"virtues_049": ("De quem diz o Alcorão que são «os irmãos dos demónios»?", ["Dos esbanjadores", "Dos viajantes", "Dos comerciantes", "Dos poetas"], "«Os esbanjadores são os irmãos dos demónios, e o Demónio é muito ingrato para com o seu Senhor» (17:27)."),
"virtues_050": ("Quais são as «duas palavras leves na língua, pesadas na balança e amadas pelo Misericordioso»?", ["«Subhana Allahi wa bi-hamdih, subhana Allahi al-Azim»", "«Allahu akbar, al-hamdu li-Llah»", "«La ilaha illa Allah, Muhammad rasulu Allah»", "«Bismi Allah, ma sha'a Allah»"], "«Duas palavras leves na língua, pesadas na balança, amadas pelo Misericordioso: Glória a Allah e louvor a Ele; glória a Allah, o Imenso.»"),
}
